import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { describe, test } from "node:test";
import { isInteractiveName } from "./interactive-names";
import { parseLocalPost } from "./local-posts";

const slug = "pewpew-source-tour";
const file = path.join(process.cwd(), "src/explainers/pewpew/post.mdx");

/** The explainer's post.md places these 17 figures, once each. Generated by scripts/pewpew-post.ts. */
const figures = [
  "pewpew-hero",
  "pewpew-pool",
  "pewpew-step",
  "pewpew-steer",
  "pewpew-frame",
  "pewpew-threads",
  "pewpew-runtimes",
  "pewpew-level",
  "pewpew-track",
  "pewpew-drones",
  "pewpew-boss",
  "pewpew-collide",
  "pewpew-bot",
  "pewpew-proof",
  "pewpew-camera",
  "pewpew-sound",
  "pewpew-flow",
];

describe("pewpew post draft", () => {
  const source = fs.readFileSync(file, "utf8");
  const lines = source.split("\n");

  test("is not in the blog folder, which the site serves", () => {
    const served = path.join(process.cwd(), "src/content/blog", `${slug}.mdx`);
    assert.equal(fs.existsSync(served), false);
  });

  test("parses as a trusted local post without throwing", () => {
    const post = parseLocalPost(slug, source);
    assert.equal(post.date, "2026-10-21T00:00:00.000Z");
    assert.ok(post.description.length <= 160);
    assert.ok(post.body.length > 0);
  });

  test("converts every figure slot into an interactive block", () => {
    const { body } = parseLocalPost(slug, source);
    const interactive = body.filter((block) => block._type === "interactive");
    assert.equal(interactive.length, 17);
    assert.deepEqual(
      interactive.map((block) => block.name),
      figures,
    );
    for (const block of interactive) {
      assert.ok(isInteractiveName(block.name), String(block.name));
    }
    const leftover = body.filter(
      (block) =>
        block._type === "block" &&
        block.children?.some((child) => child.text.includes("{{")),
    );
    assert.equal(leftover.length, 0);
  });

  test("places every figure exactly once, on its own line", () => {
    const figureLines = lines.filter((line) =>
      /^\{\{pewpew-[a-z]+\}\}$/.test(line),
    );
    assert.equal(figureLines.length, figures.length);
    for (const name of figures) {
      assert.equal(
        lines.filter((line) => line === `{{${name}}}`).length,
        1,
        name,
      );
    }
  });

  test("gives every fenced block a language", () => {
    let open = false;
    for (const line of lines) {
      if (!line.startsWith("```")) continue;
      if (!open)
        assert.notEqual(line.slice(3).trim(), "", "fence without a language");
      open = !open;
    }
    assert.equal(open, false, "unclosed fence");
  });

  test("leaves no explainer constructs behind", () => {
    assert.equal(source.includes("{{code:"), false);
    assert.equal(source.includes("^["), false);
  });
});
